import React, { useState, useEffect } from "react";
import axios from "../utils/axiosInstance";
import Search from "./Search";
import WatchListItem from "./WatchListItem";
import { DoughnutChart } from "./DoughnoutChart";

const WatchList = () => {
  const [watchlist, setWatchlist] = useState([]);

  // Fetch saved watchlist on mount
  useEffect(() => {
    fetchWatchlist();
  }, []);

  const fetchWatchlist = async () => {
    try {
      const res = await axios.get("/api/watchlist");
      setWatchlist(res.data);
    } catch (err) {
      console.error("Failed to load watchlist", err);
    }
  };

  const handleAdd = async (stock) => {
    try {
      await axios.post("/api/watchlist", { symbol: stock.symbol });
      fetchWatchlist();
    } catch (err) {
      console.error("Add to watchlist failed", err);
    }
  };

  const labels = watchlist.map((item) => item.symbol);
  const data = {
    labels,
    datasets: [
      {
        label: "Price",
        data: watchlist.map((item) => item.price),
        backgroundColor: [],
        borderColor: [],
        borderWidth: 1,
      },
    ],
  };

  return (
    <div className="watchlist-container">
      <Search onAdd={handleAdd} />
      <span className="counts">{watchlist.length} / 50</span>
      <ul className="list">
        {watchlist.map((stock) => (
          <WatchListItem key={stock.symbol} stock={stock} />
        ))}
      </ul>
      <DoughnutChart data={data} />
    </div>
  );
};

export default WatchList;
